 ld=om[om.Site.eq(site)&om.Metric.eq('LDSA')].set_index('date').value;pair=ld.to_frame('LDSA').join(expect.rename('other'),how='inner').dropna();n=len(pair);span=(pair.index.max().year-pair.index.min().year)*12+pair.index.max().month-pair.index.min().month+1 if n else 0;primary=n>=60 and n/span>=.5 if span else False;sens=n>=36 and n/span>=.5 if span else False;r=sc[sc.Site.eq(site)&sc.Metric.eq(metric)].iloc[0];assert r.common_months==n and bool(r.primary_included)==primary and bool(r.sensitivity_included)==sens,(site,metric,r.to_dict(),n,span,primary,sens,pair.head().to_dict())
